-- algo.trading_holiday seed for 2025-2026
-- generated by trading-calendar/generate_seed.py from exchange_calendars XBOM 4.13.2
-- 30 weekday holidays. Re-runnable: the upsert is idempotent.
--
-- COVERAGE ENDS 2026-12-31. After that this table answers 'no row' for
-- every date, which reads as 'trading day'. Reseed before then.

ON CONFLICT (trade_date) DO UPDATE SET
    description = EXCLUDED.description,
    source      = EXCLUDED.source,
    updated_at  = EXCLUDED.updated_at;
